mapper.select:
SELECT
    behaviorType,
    COUNT(*) as count,
    SUM(behaviorValue) as totalValue
FROM user_behavior
WHERE userId = #{userId}
  AND itemType = #{itemType}
  AND itemId = #{itemId}
  AND isDelete = 0
GROUP BY behaviorType

SELECT *
FROM user_behavior
WHERE userId = #{userId}
  AND itemType = #{itemType}
  AND isDelete = 0
ORDER BY createTime DESC
LIMIT #{limit}
